// ============================================================
//  Ballpit.jsx — Fixed & Clean Version
// ============================================================

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

class ThreeScene {
  constructor(canvas) {
    this.canvas = canvas;
    this.camera = new THREE.PerspectiveCamera(50, 1, 0.1, 100);
    this.camera.position.set(0, 0, 22);

    this.scene = new THREE.Scene();

    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      alpha: true,
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  }

  resize() {
    const rect = this.canvas.parentElement.getBoundingClientRect();
    this.camera.aspect = rect.width / rect.height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(rect.width, rect.height);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  }

  render = () => this.renderer.render(this.scene, this.camera);

  dispose() {
    this.renderer.dispose();
  }
}

class BallPhysics {
  constructor(config) {
    this.config = config;
    this.positions = new Float32Array(3 * config.count);
    this.velocities = new Float32Array(3 * config.count);
    this.sizes = new Float32Array(config.count);
    this.init();
  }

  init() {
    const { count, maxX, maxY, maxZ, minSize, maxSize } = this.config;
    for (let i = 0; i < count; i++) {
      const idx = i * 3;
      this.positions[idx] = THREE.MathUtils.randFloatSpread(maxX * 1.8);
      this.positions[idx + 1] = THREE.MathUtils.randFloatSpread(maxY * 1.6);
      this.positions[idx + 2] = THREE.MathUtils.randFloatSpread(maxZ * 1.5);

      this.velocities[idx] = THREE.MathUtils.randFloatSpread(1.2);
      this.velocities[idx + 1] = THREE.MathUtils.randFloatSpread(0.8);
      this.velocities[idx + 2] = THREE.MathUtils.randFloatSpread(0.6);

      this.sizes[i] = THREE.MathUtils.randFloat(minSize, maxSize);
    }
  }

  update(delta) {
    const { count, gravity, friction, wallBounce, maxX, maxY, maxZ } = this.config;

    for (let i = 0; i < count; i++) {
      const idx = i * 3;

      this.velocities[idx + 1] -= gravity * delta * 50;
      this.velocities[idx] *= friction;
      this.velocities[idx + 1] *= friction;
      this.velocities[idx + 2] *= friction;

      this.positions[idx] += this.velocities[idx] * delta * 50;
      this.positions[idx + 1] += this.velocities[idx + 1] * delta * 50;
      this.positions[idx + 2] += this.velocities[idx + 2] * delta * 50;

      const r = this.sizes[i];

      if (Math.abs(this.positions[idx]) + r > maxX) {
        this.positions[idx] = Math.sign(this.positions[idx]) * (maxX - r);
        this.velocities[idx] *= -wallBounce;
      }
      if (this.positions[idx + 1] - r < -maxY) {
        this.positions[idx + 1] = -maxY + r;
        this.velocities[idx + 1] *= -wallBounce;
      }
      if (Math.abs(this.positions[idx + 2]) + r > maxZ) {
        this.positions[idx + 2] = Math.sign(this.positions[idx + 2]) * (maxZ - r);
        this.velocities[idx + 2] *= -wallBounce;
      }
    }
  }
}

const Ballpit = ({
  count = 65,
  gravity = 0.09,
  friction = 0.982,
  wallBounce = 0.92,
}) => {
  const canvasRef = useRef(null);
  const animationRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const three = new ThreeScene(canvas);
    const physics = new BallPhysics({
      count,
      gravity,
      friction,
      wallBounce,
      maxX: 13,
      maxY: 9,
      maxZ: 6,
      minSize: 0.55,
      maxSize: 1.45,
    });

    const geometry = new THREE.SphereGeometry(1, 32, 32);
    const material = new THREE.MeshPhysicalMaterial({
      color: 0x6366f1,
      metalness: 0.65,
      roughness: 0.25,
      clearcoat: 1,
      clearcoatRoughness: 0.1,
    });

    const balls = new THREE.InstancedMesh(geometry, material, count);
    const dummy = new THREE.Object3D();

    const ambient = new THREE.AmbientLight(0xffffff, 0.65);
    const pointLight = new THREE.PointLight(0xa5b4fc, 2.5, 100);

    three.scene.add(ambient, pointLight, balls);

    let lastTime = 0;

    const animate = (time = 0) => {
      animationRef.current = requestAnimationFrame(animate);
      const delta = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      physics.update(delta);

      for (let i = 0; i < count; i++) {
        const idx = i * 3;
        dummy.position.set(
          physics.positions[idx],
          physics.positions[idx + 1],
          physics.positions[idx + 2]
        );
        dummy.scale.setScalar(physics.sizes[i]);
        dummy.updateMatrix();
        balls.setMatrixAt(i, dummy.matrix);
      }

      // Move light with first ball
      pointLight.position.set(
        physics.positions[0],
        physics.positions[1],
        physics.positions[2] + 3
      );

      balls.instanceMatrix.needsUpdate = true;
      three.render();
    };

    three.resize();
    animate();

    // Cleanup
    return () => {
      cancelAnimationFrame(animationRef.current);
      three.dispose();
    };
  }, [count, gravity, friction, wallBounce]);

  return (
    <canvas
      ref={canvasRef}
      className="hero__ballpit"
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Ballpit;
